":"variable","target":"method"},"defaultValue":"character constellation","id":"method","label":"Visual method","type":"text"},{"binding":{"mode":"variable","target":"structure"},"defaultValue":"placement, gaze, objects, and subtle links reveal alliances and tensions","id":"structure","label":"Composition rule","type":"textarea"},{"binding":{"mode":"generation","target":"aspectRatio"},"defaultValue":"4:5","id":"aspect-ratio","label":"Format","options":[{"label":"Portrait 4:5","value":"4:5"},{"label":"Tall 9:16","value":"9:16"},{"label":"Square 1:1","value":"1:1"},{"label":"Landscape 3:2","value":"3:2"}],"type":"aspect-ratio"}],"description":"Make a cast relationship system feel like a designed story poster rather than a diagram.","generation":{"capability":"image-generation","defaultOperation":"generate","defaultVariationCount":1,"delivery":"webmcp-import","operations":["generate","edit","variation","upscale"],"preferredMimeTypes":["image/png","image/webp"],"provider":"codex"},"id":"character-relationship-map","layout":{"arrangement":"prompt-left-output-right","mode":"seeded","preserveManualGeometry":true},"outputs":[{"aspectRatio":"4:5","count":1,"id":"primary","kind":"image","label":"Result","layoutHint":"hero","operations":["generate","edit","variation","upscale"],"required":true,"role":"primary"}],"preservation":[{"appliesTo":["method","structure"],"description":"Preserve the defining character constellation method and this composition obligation: placement, gaze, objects, and subtle links reveal alliances and tensions.","id":"creative-mechanism","label":"Creative mechanism","strength":"must"}],"prompt":{"agentInstructions":"Resolve all visible controls and reference obligations before generation. Produce one candidate by default and return it to the primary output slot.","body":"Make a cast relationship system feel like a designed story poster rather than a diagram. Create an original, polished image for this brief: {{brief}}. Use {{method}} as the visual method. Organize the image so {{structure}}. Favor one clear focal idea, intentional negative space, coherent lighting, believable depth, and material-specific detail. Do not add unrelated text, logos, watermarks, copied characters, or unsupported factual claims.","title":"Creative direction","variables":[{"defaultValue":"Eight residents of a cooperative house preparing for a difficult vote","id":"brief","label":"Creative brief","required":true,"type":"text"},{"defaultValue":"character constellation","id":"method","label":"Visual method","type":"string"},{"defaultValue":"placement, gaze, objects, and subtle links reveal alliances and tensions","id":"structure","label":"Composition rule","type":"string"}]},"schema":"prompt-canvas.prompt-workspace-template@2","source":{"creator":"Prompt Canvas","kind":"first-party","notes":"Independently authored for Prompt Canvas from a high-level creative use case.","promptUsage":"original","title":"Character relationship map"},"status":"starter","tags":["knowledge brand","character constellation poster","cast relationship map"],"thumbnail":{"alt":"First-party graphic preview for Character relationship map, illustrating character constellation.","assetPath":"/recipe-thumbnails/original-systems/character-relationship-map.svg"},"title":"Character relationship map","version":1,"x-agent-authoring":{"generationDefault":1,"origin":"independent-first-party","reviewState":"owner-requested-original-authoring"},"x-discovery":{"badges":["No photo needed","Makes 1 image"],"collection":"original-systems","complexity":"guided","inputModes":["text"],"inputSummary":["A creative brief"],"intentAliases":["character constellation poster","cast relationship map","story characters visualized"],"intents":["create"],"outputKinds":["image"],"preservationNeeds":[],"requiredInputSummary":["A short creative brief"],"subjectKinds":["person","object","place","concept"],"thumbnail":{"alt":"First-party graphic preview for Character relationship map, illustrating character constellation.","src":"/recipe-thumbnails/original-systems/character-relationship-map.svg"},"userPromise":"Make a cast relationship system feel like a designed story poster rather than a diagram."},"x-presentation":{"advancedControlIds":[],"initialView":"canvas","primaryControlIds":["brief","method","structure","aspect-ratio"],"resultEmphasis":"hero","showPromptByDefault":false}}', 'prompt-canvas.prompt-workspace-template@2', 'sha256:0b521dde5e216d27d5a3334107f320ac565a7529b71ab97865b7fc7090a000ea', 'Make a cast relationship system feel like a designed story poster rather than a diagram. Create an original, polished image for this brief: {{brief}}. Use {{method}} as the visual method. Organize the image so {{structure}}. Favor one clear focal idea, intentional negative space, coherent lighting, believable depth, and material-specific detail. Do not add unrelated text, logos, watermarks, copied characters, or unsupported factual claims.', NULL, '{"creator":"Prompt Canvas","kind":"first-party","notes":"Independently authored for Prompt Canvas from a high-level creative use case.","promptUsage":"original","title":"Character relationship map"}', 'Initial official catalog publication.', '2026-09-03T00:00:00Z', '2026-09-03T00:00:00Z');
